import json
import os

ROOT = "/Users/kevingalligan/devel/framejob/.claude/worktrees/help-docs"
OUT = (
    "/private/tmp/claude-501/-Users-kevingalligan-devel-framejob/"
    "9cfd7405-83ec-4caa-905f-7b97a20f2cc9/scratchpad/inventory/feature-fixes/text-and-shapes.json"
)

OVERRIDES = {
    "text-clip-add": {"where": "Timeline bar ▸ Add Text"},
    "text-clip-any-length": {"name": "Trim a text clip to any length"},
    "text-content": {
        "name": "Type a text clip's words",
        "summary": "Type the words in the Content box. Return applies them and ⇧Return starts a new line.",
    },
    "text-clip-picture-sections": {
        "name": "Place a text clip and add effects",
        "summary": "A text clip also has a Picture sub-tab for its position, scale, rotation, opacity and effects.",
        "where": "Clip tab ▸ Picture",
    },
    "text-set-text-tool": {
        "summary": "An agent can change any mix of a text clip's words and typography in one undo step.",
        "where": "",
    },
    "text-align": {"where": "Clip tab ▸ Text ▸ Style ▸ Align"},
    "text-vertical-align": {
        "name": "Vertical alignment",
        "summary": "Align text to the top, middle or bottom of its box, which moves it by a pixel or two at most.",
    },
    "text-style-reset": {"name": "Reset the text style"},
    "text-canvas-escape": {
        "name": "Leave the canvas editor with Esc",
        "summary": "Esc closes an unchanged editor at once. Over changed text, a sheet offers Apply, Revert and Cancel.",
    },
    "text-presets": {
        "summary": "One click gives a text clip a font, size, alignment, backdrop and position sized to your canvas.",
        "where": "Clip tab ▸ Text ▸ Presets",
    },
    "text-wrap-handles": {"where": "Drag a text clip's left or right handle on the canvas"},
    "text-reveal-typewriter": {"where": "Clip tab ▸ Text ▸ Reveal ▸ Reveal ▸ Typewriter"},
    "text-reveal-word-fade": {"where": "Clip tab ▸ Text ▸ Reveal ▸ Reveal ▸ Word Fade"},
    "text-reveal-line-rise": {"where": "Clip tab ▸ Text ▸ Reveal ▸ Reveal ▸ Line Rise"},
    "text-reveal-in-out": {"where": "Clip tab ▸ Text ▸ Reveal ▸ In, Out"},
    "shape-kind-line": {
        "summary": "A straight line that starts diagonally across its box, with two ends you can drag.",
    },
    "shape-box-handles": {
        "summary": "Drag a handle to resize a shape's box, keeping the stroke's thickness. ⇧ frees the aspect ratio on a corner.",
        "keys": "⇧-drag",
        "where": "Drag a shape's handle on the canvas",
    },
    "shape-clip-picture-sections": {
        "name": "Place a shape and add effects",
        "summary": "A shape also has a Picture sub-tab for its position, scale, rotation, opacity and effects.",
        "where": "Clip tab ▸ Picture",
    },
    "shape-fill": {"summary": "Fill a rectangle or ellipse with a flat colour."},
    "shape-arrowheads": {
        "summary": "Put a head on the start, the end or both ends of an arrow. Heads show only when Kind is Arrow.",
    },
    "shape-no-animation": {"where": "Clip tab ▸ Shape"},
    "shape-set-shape-tool": {
        "summary": "An agent can change any of a shape's settings in one call and leave the rest as they are.",
        "where": "",
    },
    "gradient-angle": {"summary": "Set a linear gradient's direction, from 0 to 360°."},
    "gradient-stops": {"where": "Clip tab ▸ Shape ▸ Gradient ▸ Stop 1, Stop 2 and so on"},
    "image-clip-place": {
        "summary": "Import a picture as you would a movie, then drag it to a track or the canvas. It lands as a five-second clip.",
    },
    "image-clip-picture-sections": {
        "name": "Picture and Color controls on an image clip",
        "summary": "An image clip has every Picture section a video clip has but Layout and Cursor, and a Color sub-tab for grading.",
        "where": "Clip tab ▸ Picture",
    },
}

PREFIX = "Inspector ▸ Clip ▸ "

data = json.load(open(os.path.join(ROOT, "docs/site/src/data/features.json"), encoding="utf-8"))
section = next(s for s in data["sections"] if s["id"] == "text-and-shapes")
rows = {f["id"]: f for f in section["features"]}
assert set(OVERRIDES) <= set(rows), set(OVERRIDES) - set(rows)

updates = []
for row_id, row in rows.items():
    wanted = dict(OVERRIDES.get(row_id, {}))
    where = row.get("where", "")
    if "where" not in wanted and where.startswith(PREFIX):
        wanted["where"] = "Clip tab ▸ " + where[len(PREFIX):]
    changed = {k: v for k, v in wanted.items() if row.get(k, "") != v}
    if changed:
        updates.append({"id": row_id, **changed})

for update in updates:
    summary = update.get("summary", "")
    assert len(summary) <= 140, (update["id"], len(summary))

left = [r["id"] for r in rows.values() if not any(u["id"] == r["id"] and "where" in u for u in updates)
        and r.get("where", "").startswith("Inspector")]
assert not left, left

os.makedirs(os.path.dirname(OUT), exist_ok=True)
with open(OUT, "w", encoding="utf-8") as out:
    json.dump({"updates": updates, "remove": []}, out, ensure_ascii=False, indent=2)
    out.write("\n")
print("rows", len(rows), "updated", len(updates), "removed 0")

